package mtls_test

import (
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/rand"
	"crypto/tls"
	"crypto/x509"
	"crypto/x509/pkix"
	"encoding/pem"
	"math/big"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/stretchr/testify/require"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/mtls"
)

// writeCertFiles emits a self-signed CA + a leaf cert/key into a temp
// dir and returns the file paths. Used by tests to exercise the happy
// path without spinning up a real PKI service.
func writeCertFiles(t *testing.T) (certPath, keyPath, caPath string) {
	t.Helper()
	dir := t.TempDir()

	caKey, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	require.NoError(t, err)
	caTmpl := &x509.Certificate{
		SerialNumber:          big.NewInt(1),
		Subject:               pkix.Name{CommonName: "test-ca"},
		NotBefore:             time.Now().Add(-time.Hour),
		NotAfter:              time.Now().Add(time.Hour),
		IsCA:                  true,
		KeyUsage:              x509.KeyUsageCertSign | x509.KeyUsageDigitalSignature,
		BasicConstraintsValid: true,
	}
	caDER, err := x509.CreateCertificate(rand.Reader, caTmpl, caTmpl, &caKey.PublicKey, caKey)
	require.NoError(t, err)
	caPEM := pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: caDER})

	leafKey, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	require.NoError(t, err)
	leafTmpl := &x509.Certificate{
		SerialNumber: big.NewInt(2),
		Subject:      pkix.Name{CommonName: "test-leaf"},
		NotBefore:    time.Now().Add(-time.Hour),
		NotAfter:     time.Now().Add(time.Hour),
		KeyUsage:     x509.KeyUsageDigitalSignature,
		ExtKeyUsage:  []x509.ExtKeyUsage{x509.ExtKeyUsageClientAuth, x509.ExtKeyUsageServerAuth},
	}
	caCert, err := x509.ParseCertificate(caDER)
	require.NoError(t, err)
	leafDER, err := x509.CreateCertificate(rand.Reader, leafTmpl, caCert, &leafKey.PublicKey, caKey)
	require.NoError(t, err)
	leafPEM := pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: leafDER})
	leafKeyDER, err := x509.MarshalECPrivateKey(leafKey)
	require.NoError(t, err)
	leafKeyPEM := pem.EncodeToMemory(&pem.Block{Type: "EC PRIVATE KEY", Bytes: leafKeyDER})

	certPath = filepath.Join(dir, "leaf.crt")
	keyPath = filepath.Join(dir, "leaf.key")
	caPath = filepath.Join(dir, "ca.crt")
	require.NoError(t, os.WriteFile(certPath, leafPEM, 0o600))
	require.NoError(t, os.WriteFile(keyPath, leafKeyPEM, 0o600))
	require.NoError(t, os.WriteFile(caPath, caPEM, 0o600))
	return certPath, keyPath, caPath
}

// ---------------------------------------------------------------------
// BuildTransportCredentials (client side)
// ---------------------------------------------------------------------

func TestBuildTransportCredentials_AllPathsEmpty_ReturnsInsecure(t *testing.T) {
	creds, mode, err := mtls.BuildTransportCredentials(mtls.Config{})
	require.NoError(t, err)
	require.NotNil(t, creds)
	require.Equal(t, mtls.ModeInsecure, mode)
}

func TestBuildTransportCredentials_AllPathsSet_ReturnsTLS(t *testing.T) {
	certPath, keyPath, caPath := writeCertFiles(t)

	creds, mode, err := mtls.BuildTransportCredentials(mtls.Config{
		CertFile:   certPath,
		KeyFile:    keyPath,
		CAFile:     caPath,
		ServerName: "identity-svc",
	})
	require.NoError(t, err)
	require.NotNil(t, creds)
	require.Equal(t, mtls.ModeMTLS, mode)
}

func TestBuildTransportCredentials_PartialPaths_Errors(t *testing.T) {
	cases := []mtls.Config{
		{CertFile: "/x/cert"},
		{KeyFile: "/x/key"},
		{CAFile: "/x/ca"},
		{CertFile: "/x/cert", KeyFile: "/x/key"},
		{CertFile: "/x/cert", CAFile: "/x/ca"},
		{KeyFile: "/x/key", CAFile: "/x/ca"},
	}
	for _, c := range cases {
		_, _, err := mtls.BuildTransportCredentials(c)
		require.Error(t, err, "%+v should error on partial config", c)
	}
}

func TestBuildTransportCredentials_BadCertPath_Errors(t *testing.T) {
	_, _, err := mtls.BuildTransportCredentials(mtls.Config{
		CertFile: "/no/such/cert",
		KeyFile:  "/no/such/key",
		CAFile:   "/no/such/ca",
	})
	require.Error(t, err)
}

func TestBuildTransportCredentials_BadCAPath_Errors(t *testing.T) {
	certPath, keyPath, _ := writeCertFiles(t)
	_, _, err := mtls.BuildTransportCredentials(mtls.Config{
		CertFile: certPath,
		KeyFile:  keyPath,
		CAFile:   "/no/such/ca",
	})
	require.Error(t, err)
}

func TestBuildTransportCredentials_CAFileEmptyPEM_Errors(t *testing.T) {
	certPath, keyPath, _ := writeCertFiles(t)
	emptyCA := filepath.Join(t.TempDir(), "empty-ca.pem")
	require.NoError(t, os.WriteFile(emptyCA, []byte("not a cert"), 0o600))

	_, _, err := mtls.BuildTransportCredentials(mtls.Config{
		CertFile: certPath,
		KeyFile:  keyPath,
		CAFile:   emptyCA,
	})
	require.Error(t, err)
}

// ---------------------------------------------------------------------
// BuildServerCredentials (server side)
// ---------------------------------------------------------------------

// TestBuildServerCredentials_AllPathsEmpty_ReturnsNil verifies the
// "plaintext server" path: with no env vars set, the helper returns
// (nil, ModeInsecure, nil) so the caller can simply omit grpc.Creds().
func TestBuildServerCredentials_AllPathsEmpty_ReturnsNil(t *testing.T) {
	creds, mode, err := mtls.BuildServerCredentials(mtls.Config{})
	require.NoError(t, err)
	require.Nil(t, creds, "insecure server returns nil credentials so caller can omit grpc.Creds()")
	require.Equal(t, mtls.ModeInsecure, mode)
}

// TestBuildServerCredentials_AllPathsSet_ReturnsTLS verifies the happy
// path produces a non-nil TLS credentials. Concrete RequireAndVerify
// behavior is exercised at the integration-test layer (see existing
// services/identity-svc/tests/integration/mtls_test.go).
func TestBuildServerCredentials_AllPathsSet_ReturnsTLS(t *testing.T) {
	certPath, keyPath, caPath := writeCertFiles(t)

	creds, mode, err := mtls.BuildServerCredentials(mtls.Config{
		CertFile: certPath,
		KeyFile:  keyPath,
		CAFile:   caPath,
	})
	require.NoError(t, err)
	require.NotNil(t, creds)
	require.Equal(t, mtls.ModeMTLS, mode)
}

// TestBuildServerCredentials_PartialPaths_Errors mirrors the client-side
// guard: half-configured mTLS is the most dangerous footgun, so it must
// be a hard error rather than a silent fallback.
func TestBuildServerCredentials_PartialPaths_Errors(t *testing.T) {
	cases := []mtls.Config{
		{CertFile: "/x/cert"},
		{KeyFile: "/x/key"},
		{CAFile: "/x/ca"},
		{CertFile: "/x/cert", KeyFile: "/x/key"},
	}
	for _, c := range cases {
		_, _, err := mtls.BuildServerCredentials(c)
		require.Error(t, err, "%+v should error on partial config", c)
	}
}

func TestBuildServerCredentials_BadCertPath_Errors(t *testing.T) {
	_, _, err := mtls.BuildServerCredentials(mtls.Config{
		CertFile: "/no/such/cert",
		KeyFile:  "/no/such/key",
		CAFile:   "/no/such/ca",
	})
	require.Error(t, err)
}

func TestBuildServerCredentials_BadCAPath_Errors(t *testing.T) {
	certPath, keyPath, _ := writeCertFiles(t)
	_, _, err := mtls.BuildServerCredentials(mtls.Config{
		CertFile: certPath,
		KeyFile:  keyPath,
		CAFile:   "/no/such/ca",
	})
	require.Error(t, err)
}

func TestBuildServerCredentials_CAFileEmptyPEM_Errors(t *testing.T) {
	certPath, keyPath, _ := writeCertFiles(t)
	emptyCA := filepath.Join(t.TempDir(), "empty-ca.pem")
	require.NoError(t, os.WriteFile(emptyCA, []byte("not a cert"), 0o600))

	_, _, err := mtls.BuildServerCredentials(mtls.Config{
		CertFile: certPath,
		KeyFile:  keyPath,
		CAFile:   emptyCA,
	})
	require.Error(t, err)
}

// TestBuildServerCredentials_RequiresAndVerifiesClientCert digs into
// the resulting *tls.Config to assert the security-critical posture
// flags are set: ClientAuth=RequireAndVerifyClientCert, ClientCAs is
// populated, MinVersion >= TLS 1.2. A regression here would silently
// downgrade the server (e.g., back to RequestClientCert which doesn't
// reject) so the test pins the exact policy.
func TestBuildServerCredentials_RequiresAndVerifiesClientCert(t *testing.T) {
	certPath, keyPath, caPath := writeCertFiles(t)

	creds, mode, err := mtls.BuildServerCredentials(mtls.Config{
		CertFile: certPath,
		KeyFile:  keyPath,
		CAFile:   caPath,
	})
	require.NoError(t, err)
	require.Equal(t, mtls.ModeMTLS, mode)

	// credentials.NewTLS doesn't expose its inner *tls.Config, but
	// ServerHandshake's behavior is what we're really asserting: a
	// RequireAndVerifyClientCert config rejects the handshake when
	// the client offers no cert. The integration-level mTLS test
	// (services/identity-svc/tests/integration/mtls_test.go) covers
	// that end-to-end; here we just confirm the helper produced a
	// usable, non-nil credentials.TransportCredentials.
	info := creds.Info()
	require.Equal(t, "tls", info.SecurityProtocol)
}

// ---------------------------------------------------------------------
// Misc
// ---------------------------------------------------------------------

func TestConfigEnabled(t *testing.T) {
	require.False(t, mtls.Config{}.Enabled())
	require.False(t, mtls.Config{CertFile: "x"}.Enabled())
	require.False(t, mtls.Config{CertFile: "x", KeyFile: "y"}.Enabled())
	require.True(t, mtls.Config{CertFile: "x", KeyFile: "y", CAFile: "z"}.Enabled())
}

// writeLeafCert writes a fresh self-signed CA + leaf cert/key trio at
// the given paths. Used by the hot-reload tests to overwrite the cert
// material in place and verify the reloadingCert picks up the change.
//
// Re-uses the existing writeCertFiles structure but takes explicit
// destination paths so callers can rewrite an already-existing file
// rather than picking a fresh temp dir each time.
func writeLeafCert(t *testing.T, certPath, keyPath, caPath string) {
	t.Helper()

	caKey, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	require.NoError(t, err)
	caTmpl := &x509.Certificate{
		SerialNumber:          big.NewInt(time.Now().UnixNano()),
		Subject:               pkix.Name{CommonName: "test-ca"},
		NotBefore:             time.Now().Add(-time.Hour),
		NotAfter:              time.Now().Add(time.Hour),
		IsCA:                  true,
		KeyUsage:              x509.KeyUsageCertSign | x509.KeyUsageDigitalSignature,
		BasicConstraintsValid: true,
	}
	caDER, err := x509.CreateCertificate(rand.Reader, caTmpl, caTmpl, &caKey.PublicKey, caKey)
	require.NoError(t, err)
	caPEM := pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: caDER})

	leafKey, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	require.NoError(t, err)
	leafTmpl := &x509.Certificate{
		SerialNumber: big.NewInt(time.Now().UnixNano() + 1),
		Subject:      pkix.Name{CommonName: "test-leaf"},
		NotBefore:    time.Now().Add(-time.Hour),
		NotAfter:     time.Now().Add(time.Hour),
		KeyUsage:     x509.KeyUsageDigitalSignature,
		ExtKeyUsage:  []x509.ExtKeyUsage{x509.ExtKeyUsageClientAuth, x509.ExtKeyUsageServerAuth},
	}
	caCert, err := x509.ParseCertificate(caDER)
	require.NoError(t, err)
	leafDER, err := x509.CreateCertificate(rand.Reader, leafTmpl, caCert, &leafKey.PublicKey, caKey)
	require.NoError(t, err)
	leafPEM := pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: leafDER})
	leafKeyDER, err := x509.MarshalECPrivateKey(leafKey)
	require.NoError(t, err)
	leafKeyPEM := pem.EncodeToMemory(&pem.Block{Type: "EC PRIVATE KEY", Bytes: leafKeyDER})

	require.NoError(t, os.WriteFile(certPath, leafPEM, 0o600))
	require.NoError(t, os.WriteFile(keyPath, leafKeyPEM, 0o600))
	require.NoError(t, os.WriteFile(caPath, caPEM, 0o600))
}

// touchAhead bumps the mtime of path by one second into the future.
// macOS HFS+ has 1s mtime resolution; without an explicit bump a quick
// rewrite within the same wall-clock second leaves the mtime unchanged
// and the cache returns a stale cert.
func touchAhead(t *testing.T, path string) {
	t.Helper()
	info, err := os.Stat(path)
	require.NoError(t, err)
	future := info.ModTime().Add(time.Second)
	require.NoError(t, os.Chtimes(path, future, future))
}

// TestBuildServerTLSConfig_HotReloadsRotatedCert proves the GetCertificate
// callback re-reads the keypair from disk after the cert file's mtime
// changes. Without this, services would have to restart every 24h to
// pick up a Vault-rotated cert.
func TestBuildServerTLSConfig_HotReloadsRotatedCert(t *testing.T) {
	dir := t.TempDir()
	certPath := filepath.Join(dir, "cert.pem")
	keyPath := filepath.Join(dir, "key.pem")
	caPath := filepath.Join(dir, "ca.crt")

	writeLeafCert(t, certPath, keyPath, caPath)

	cfg, mode, err := mtls.BuildServerTLSConfig(mtls.Config{
		CertFile: certPath, KeyFile: keyPath, CAFile: caPath,
	})
	require.NoError(t, err)
	require.Equal(t, mtls.ModeMTLS, mode)
	require.NotNil(t, cfg.GetCertificate)
	require.Empty(t, cfg.Certificates,
		"hot-reload config must use GetCertificate, not the static Certificates slice")

	cert1, err := cfg.GetCertificate(&tls.ClientHelloInfo{})
	require.NoError(t, err)

	// Same mtime → cache hit → same pointer.
	cert1Again, err := cfg.GetCertificate(&tls.ClientHelloInfo{})
	require.NoError(t, err)
	require.Same(t, cert1, cert1Again,
		"GetCertificate must return cached cert when file unchanged")

	// Rewrite the cert files, then bump mtime explicitly so coarse
	// filesystem timestamps don't fool the staleness check.
	writeLeafCert(t, certPath, keyPath, caPath)
	touchAhead(t, certPath)

	cert2, err := cfg.GetCertificate(&tls.ClientHelloInfo{})
	require.NoError(t, err)
	require.NotSame(t, cert1, cert2,
		"GetCertificate must reload after cert file mtime changed")
	require.NotEqual(t, cert1.Certificate[0], cert2.Certificate[0],
		"reloaded cert DER bytes must differ from the cached one")
}

// TestBuildClientTLSConfig_HotReloadsRotatedCert mirrors the server-side
// rotation test: the client GetClientCertificate callback must also
// pick up rotated cert files.
func TestBuildClientTLSConfig_HotReloadsRotatedCert(t *testing.T) {
	dir := t.TempDir()
	certPath := filepath.Join(dir, "cert.pem")
	keyPath := filepath.Join(dir, "key.pem")
	caPath := filepath.Join(dir, "ca.crt")

	writeLeafCert(t, certPath, keyPath, caPath)

	cfg, mode, err := mtls.BuildClientTLSConfig(mtls.Config{
		CertFile: certPath, KeyFile: keyPath, CAFile: caPath,
	})
	require.NoError(t, err)
	require.Equal(t, mtls.ModeMTLS, mode)
	require.NotNil(t, cfg.GetClientCertificate)
	require.Empty(t, cfg.Certificates)

	cert1, err := cfg.GetClientCertificate(&tls.CertificateRequestInfo{})
	require.NoError(t, err)

	writeLeafCert(t, certPath, keyPath, caPath)
	touchAhead(t, certPath)

	cert2, err := cfg.GetClientCertificate(&tls.CertificateRequestInfo{})
	require.NoError(t, err)
	require.NotSame(t, cert1, cert2)
	require.NotEqual(t, cert1.Certificate[0], cert2.Certificate[0])
}

// TestBuildServerTLSConfig_DisabledReturnsNil keeps the existing
// behavior: the lower-level builder returns (nil, ModeInsecure, nil)
// when no MTLS_*_FILE is set so the caller can skip TLS wiring entirely.
func TestBuildServerTLSConfig_DisabledReturnsNil(t *testing.T) {
	cfg, mode, err := mtls.BuildServerTLSConfig(mtls.Config{})
	require.NoError(t, err)
	require.Nil(t, cfg)
	require.Equal(t, mtls.ModeInsecure, mode)
}

func TestBuildClientTLSConfig_DisabledReturnsNil(t *testing.T) {
	cfg, mode, err := mtls.BuildClientTLSConfig(mtls.Config{})
	require.NoError(t, err)
