// Package mtls builds gRPC TransportCredentials for east-west service-to-
// service traffic.
//
// The platform-wide mTLS rollout (T1.1) is staged behind Vault PKI
// infrastructure. Until production certs are mounted by Vault Agent
// sidecars, services dial and listen with insecure transport credentials.
// This package decouples that transition from the rest of the service
// code: when the operator sets MTLS_*_FILE env vars, BuildTransportCredentials
// (client) / BuildServerCredentials (server) return real TLS bundles; when
// they're unset, both report ModeInsecure so the caller can log it. Partial
// configuration (cert without key, ca without cert, etc.) is an explicit
// error so operators don't end up silently in insecure mode after a typo.
//
// The shared lib supersedes the per-service copies that lived under
// services/migrator-{identity,org}/internal/mtls/. New services must import
// this package; the migrator copies are kept temporarily as thin re-exports
// pending their next refactor pass.
//
// T1.1 phase 2d adds hot-reload: the *tls.Config returned by Build*TLSConfig
// uses GetCertificate / GetClientCertificate callbacks that re-read the cert
// and key files from disk when their mtime changes. A Vault Agent sidecar
// (or an operator re-running vault-pki-bootstrap) can swap the files
// in place; in-flight gRPC connections finish with the old cert and new
// connections handshake against the rotated cert. The CA bundle is loaded
// once at startup — root-CA rotation still requires a service restart, but
// the leaf certs (24h TTL) flow continuously.
//
// P0-05 closes the fail-open gap: ModeInsecure used to be something callers
// merely logged. EnforceMode turns it into a hard startup failure unless the
// operator has explicitly opted into plaintext via AllowInsecureEnvVar — so
// missing/misconfigured certs can no longer silently downgrade production
// traffic to plaintext. Every Build*Credentials call site must pair its mode
// with an EnforceMode check.
package mtls

import (
	"crypto/tls"
	"crypto/x509"
	"errors"
	"fmt"
	"os"
	"strings"
	"sync"
	"time"

	"google.golang.org/grpc/credentials"
	"google.golang.org/grpc/credentials/insecure"
)

// AllowInsecureEnvVar is the explicit dev/CI opt-out checked by EnforceMode.
// Unset (or falsy) means "insecure transport is not allowed" — the safe
// default in every deployed environment.
const AllowInsecureEnvVar = "OMNICORE_ALLOW_INSECURE_MTLS"

// EnforceMode fails startup when mode is ModeInsecure, unless the operator
// has set AllowInsecureEnvVar to a truthy value (1/true/yes/on). Call this
// immediately after every BuildServerCredentials / BuildTransportCredentials
// (or the lower-level Build*TLSConfig) call — a bare log line is not enough,
// because nobody reliably reads startup logs before plaintext traffic starts
// flowing.
func EnforceMode(mode Mode) error {
	if mode != ModeInsecure {
		return nil
	}
	if isTruthy(os.Getenv(AllowInsecureEnvVar)) {
		return nil
	}
	return fmt.Errorf(
		"mtls: refusing to start with insecure (plaintext, unauthenticated) transport; "+
			"set MTLS_CERT_FILE/MTLS_KEY_FILE/MTLS_CA_FILE, or set %s=true for local dev/CI only",
		AllowInsecureEnvVar,
	)
}

// Mode reports which transport credentials Build*Credentials returned.
// Used by callers to log/observe mTLS posture per dial or per listener.
type Mode int

const (
	// ModeInsecure: insecure.NewCredentials() (client) or no TLS at all
	// (server, in which case the returned credentials.TransportCredentials
	// is nil — caller must NOT pass it to grpc.Creds). Caller should log
	// a warning so operators see clearly that mTLS is off.
	ModeInsecure Mode = iota
	// ModeMTLS: real mTLS with the configured cert + CA bundle. Server
	// side requires-and-verifies the client cert.
	ModeMTLS
)

// String returns a stable, lowercase token suitable for log fields.
func (m Mode) String() string {
	switch m {
	case ModeMTLS:
		return "mtls"
	case ModeInsecure:
		return "insecure"
	default:
		return "unknown"
	}
}

// Config carries the file paths needed to assemble an mTLS TLS config.
// CertFile/KeyFile/CAFile are all empty in the dev/CI default; production
// sets all three. ServerName is client-side only and overrides the SNI
// the dial expects from the server's leaf cert; ignored on the server
// side. Empty ServerName falls back to gRPC's default (the dial target's
// host part).
type Config struct {
	CertFile   string
	KeyFile    string
	CAFile     string
	ServerName string
}

// Enabled reports whether the config has the three required file paths
// set. Useful for "should I wire mTLS or skip" branching at the caller
// without invoking the build helpers.
func (c Config) Enabled() bool {
	return c.CertFile != "" && c.KeyFile != "" && c.CAFile != ""
}

// BuildTransportCredentials returns gRPC TransportCredentials for an
// outbound dial. Returns ModeInsecure when all three file paths are
// empty (dev/CI default); ModeMTLS when all three are set and load
// cleanly. Partial configuration is an error.
func BuildTransportCredentials(c Config) (credentials.TransportCredentials, Mode, error) {
	cfg, mode, err := BuildClientTLSConfig(c)
	if err != nil {
		return nil, mode, err
	}
	if cfg == nil {
		return insecure.NewCredentials(), ModeInsecure, nil
	}
	return credentials.NewTLS(cfg), mode, nil
}

// BuildServerCredentials returns gRPC TransportCredentials for an inbound
// listener. The server enforces tls.RequireAndVerifyClientCert against the
// configured CA bundle, so any caller without a valid client cert signed
// by the same CA fails the TLS handshake before the JWT interceptor runs.
//
// Returns (nil, ModeInsecure, nil) when all three file paths are empty —
// the caller is expected to omit grpc.Creds() entirely in that case
// (gRPC defaults to plaintext h2c). Partial configuration is an error.
func BuildServerCredentials(c Config) (credentials.TransportCredentials, Mode, error) {
	cfg, mode, err := BuildServerTLSConfig(c)
	if err != nil || cfg == nil {
		return nil, mode, err
	}
	return credentials.NewTLS(cfg), mode, nil
}

// BuildServerTLSConfig is the lower-level builder behind BuildServerCredentials.
// Returns the assembled *tls.Config so callers that need the policy outside
// of gRPC (HTTPS listeners, in-process tests, custom credential wrappers) can
// reuse the same hot-reload behavior.
//
// When mTLS is disabled (all three file paths empty) returns
// (nil, ModeInsecure, nil) — a nil *tls.Config means "no TLS"; the caller
// must skip grpc.Creds()/tls.NewListener entirely. Partial configuration
// is an error.
//
// The returned config:
//   - Uses GetCertificate (rather than Certificates) so cert + key files
//     are re-read on each handshake when their mtime changes (T1.1 phase 2d).
//   - Sets ClientAuth=RequireAndVerifyClientCert with ClientCAs from CAFile
//     so the inbound handshake rejects unauthorized clients before the
//     application interceptor runs.
//   - Pins MinVersion=TLS1.2.
func BuildServerTLSConfig(c Config) (*tls.Config, Mode, error) {
	if err := validateAllOrNone(c); err != nil {
		return nil, ModeInsecure, err
	}
	if !c.Enabled() {
		return nil, ModeInsecure, nil
	}

	rc, err := newReloadingCert(c.CertFile, c.KeyFile)
	if err != nil {
		return nil, ModeInsecure, err
	}
	pool, err := loadCAPool(c.CAFile)
	if err != nil {
		return nil, ModeInsecure, err
	}

	return &tls.Config{
		MinVersion: tls.VersionTLS12,
		ClientAuth: tls.RequireAndVerifyClientCert,
		ClientCAs:  pool,
		GetCertificate: func(_ *tls.ClientHelloInfo) (*tls.Certificate, error) {
			return rc.get()
		},
	}, ModeMTLS, nil
}

// BuildClientTLSConfig is the lower-level builder behind
// BuildTransportCredentials. Returns the assembled *tls.Config so callers
// outside of gRPC (raw net/http, custom dialers) can reuse the same
// hot-reload behavior.
//
// When mTLS is disabled (all three file paths empty) returns
// (nil, ModeInsecure, nil) — caller falls back to insecure transport
// (BuildTransportCredentials wraps that fallback in
// insecure.NewCredentials()).
//
// The returned config:
//   - Uses GetClientCertificate (rather than Certificates) so cert + key
//     files are re-read on each handshake when their mtime changes
//     (T1.1 phase 2d).
//   - Sets RootCAs from CAFile so the client verifies the server cert
//     against the same internal CA the server was issued from.
//   - Sets ServerName from Config.ServerName (empty falls back to gRPC's
//     default — the dial target's host part).
//   - Pins MinVersion=TLS1.2.
func BuildClientTLSConfig(c Config) (*tls.Config, Mode, error) {
	if err := validateAllOrNone(c); err != nil {
		return nil, ModeInsecure, err
	}
	if !c.Enabled() {
		return nil, ModeInsecure, nil
	}

	rc, err := newReloadingCert(c.CertFile, c.KeyFile)
	if err != nil {
		return nil, ModeInsecure, err
	}
	pool, err := loadCAPool(c.CAFile)
	if err != nil {
		return nil, ModeInsecure, err
	}

	return &tls.Config{
		MinVersion: tls.VersionTLS12,
		RootCAs:    pool,
		ServerName: c.ServerName,
		GetClientCertificate: func(_ *tls.CertificateRequestInfo) (*tls.Certificate, error) {
			return rc.get()
		},
	}, ModeMTLS, nil
}

// reloadingCert is the cert+key cache behind GetCertificate /
// GetClientCertificate. On each call it stats the cert file; if the mtime
// matches the last load it returns the cached *tls.Certificate, otherwise
// it re-reads the keypair from disk and updates the cache.
//
// Stat is cheap (~10us) compared to a TLS handshake (>1ms), so the
// per-handshake overhead is acceptable. The cache hit path takes the
// mutex briefly; concurrent handshakes serialize on Stat but not on the
// (slower) keypair load when the file is unchanged.
type reloadingCert struct {
	certFile, keyFile string
	mu                sync.Mutex
	cached            *tls.Certificate
	mtime             time.Time
}

// newReloadingCert returns a reloadingCert with the keypair eagerly
// loaded so the caller fails fast on a bad cert path instead of
// surfacing the error on the first handshake.
func newReloadingCert(certFile, keyFile string) (*reloadingCert, error) {
	rc := &reloadingCert{certFile: certFile, keyFile: keyFile}
	if _, err := rc.get(); err != nil {
		return nil, err
	}
	return rc, nil
}

func (rc *reloadingCert) get() (*tls.Certificate, error) {
	rc.mu.Lock()
	defer rc.mu.Unlock()

	info, err := os.Stat(rc.certFile)
	if err != nil {
		return nil, fmt.Errorf("mtls: stat cert file %q: %w", rc.certFile, err)
	}
	if rc.cached != nil && info.ModTime().Equal(rc.mtime) {
		return rc.cached, nil
	}
	cert, err := tls.LoadX509KeyPair(rc.certFile, rc.keyFile)
	if err != nil {
		return nil, fmt.Errorf("mtls: reload keypair (cert=%q key=%q): %w", rc.certFile, rc.keyFile, err)
	}
	rc.cached = &cert
	rc.mtime = info.ModTime()
	return rc.cached, nil
}

// loadCAPool reads caFile and returns an x509.CertPool containing every
// PEM block in it. The CA bundle is treated as static — root-CA rotation
// requires a service restart so we don't pay the per-handshake stat cost
// for a value that doesn't change.
func loadCAPool(caFile string) (*x509.CertPool, error) {
	caPEM, err := os.ReadFile(caFile)
	if err != nil {
		return nil, fmt.Errorf("mtls: read ca file %q: %w", caFile, err)
	}
	pool := x509.NewCertPool()
	if !pool.AppendCertsFromPEM(caPEM) {
		return nil, fmt.Errorf("mtls: ca file %q contains no parseable PEM certificates", caFile)
	}
	return pool, nil
}

// isTruthy matches the fleet-wide 1/true/yes/on convention used by the
// Python config helpers (bool_env) so the escape hatch reads the same
// across both stacks.
func isTruthy(raw string) bool {
	switch strings.ToLower(strings.TrimSpace(raw)) {
	case "1", "true", "yes", "on":
		return true
	default:
		return false
	}
}

func validateAllOrNone(c Config) error {
	cert, key, ca := c.CertFile != "", c.KeyFile != "", c.CAFile != ""
	if cert == key && key == ca {
		return nil
	}
	return errors.New("mtls: CertFile, KeyFile, and CAFile must be set together (or all empty)")
}


