// TestBuildServerCredentials_RequiresAndVerifiesClientCert digs into
// the resulting *tls.Config to assert the security-critical posture
// flags are set: ClientAuth=RequireAndVerifyClientCert, ClientCAs is
// populated, MinVersion >= TLS 1.2. A regression here would silently
// downgrade the server (e.g., back to RequestClientCert which doesn't
// reject) so the test pins the exact policy.
func TestBuildServerCredentials_RequiresAndVerifiesClientCert(t *testing.T) {
	certPath, keyPath, caPath := writeCertFiles(t)

	creds, mode, err := mtls.BuildServerCredentials(mtls.Config{
