// writeLeafCert writes a fresh self-signed CA + leaf cert/key trio at
// the given paths. Used by the hot-reload tests to overwrite the cert
// material in place and verify the reloadingCert picks up the change.
//
// Re-uses the existing writeCertFiles structure but takes explicit
// destination paths so callers can rewrite an already-existing file
// rather than picking a fresh temp dir each time.
func writeLeafCert(t *testing.T, certPath, keyPath, caPath string) {
	t.Helper()

	caKey, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	require.NoError(t, err)
	caTmpl := &x509.Certificate{
		SerialNumber:          big.NewInt(time.Now().UnixNano()),
		Subject:               pkix.Name{CommonName: "test-ca"},
		NotBefore:             time.Now().Add(-time.Hour),
		NotAfter:              time.Now().Add(time.Hour),
		IsCA:                  true,
		KeyUsage:              x509.KeyUsageCertSign | x509.KeyUsageDigitalSignature,
		BasicConstraintsValid: true,
	}
	caDER, err := x509.CreateCertificate(rand.Reader, caTmpl, caTmpl, &caKey.PublicKey, caKey)
	require.NoError(t, err)
	caPEM := pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: caDER})

	leafKey, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	require.NoError(t, err)
	leafTmpl := &x509.Certificate{
		SerialNumber: big.NewInt(time.Now().UnixNano() + 1),
		Subject:      pkix.Name{CommonName: "test-leaf"},
		NotBefore:    time.Now().Add(-time.Hour),
		NotAfter:     time.Now().Add(time.Hour),
		KeyUsage:     x509.KeyUsageDigitalSignature,
		ExtKeyUsage:  []x509.ExtKeyUsage{x509.ExtKeyUsageClientAuth, x509.ExtKeyUsageServerAuth},
	}
	caCert, err := x509.ParseCertificate(caDER)
	require.NoError(t, err)
	leafDER, err := x509.CreateCertificate(rand.Reader, leafTmpl, caCert, &leafKey.PublicKey, caKey)
	require.NoError(t, err)
	leafPEM := pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: leafDER})
	leafKeyDER, err := x509.MarshalECPrivateKey(leafKey)
	require.NoError(t, err)
	leafKeyPEM := pem.EncodeToMemory(&pem.Block{Type: "EC PRIVATE KEY", Bytes: leafKeyDER})

	require.NoError(t, os.WriteFile(certPath, leafPEM, 0o600))
	require.NoError(t, os.WriteFile(keyPath, leafKeyPEM, 0o600))
	require.NoError(t, os.WriteFile(caPath, caPEM, 0o600))
}

// touchAhead bumps the mtime of path by one second into the future.
// macOS HFS+ has 1s mtime resolution; without an explicit bump a quick
// rewrite within the same wall-clock second leaves the mtime unchanged
// and the cache returns a stale cert.
func touchAhead(t *testing.T, path string) {
	t.Helper()
	info, err := os.Stat(path)
	require.NoError(t, err)
	future := info.ModTime().Add(time.Second)
	require.NoError(t, os.Chtimes(path, future, future))
}

// TestBuildServerTLSConfig_HotReloadsRotatedCert proves the GetCertificate
// callback re-reads the keypair from disk after the cert file's mtime
// changes. Without this, services would have to restart every 24h to
// pick up a Vault-rotated cert.
func TestBuildServerTLSConfig_HotReloadsRotatedCert(t *testing.T) {
	dir := t.TempDir()
	certPath := filepath.Join(dir, "cert.pem")
	keyPath := filepath.Join(dir, "key.pem")
	caPath := filepath.Join(dir, "ca.crt")

	writeLeafCert(t, certPath, keyPath, caPath)

	cfg, mode, err := mtls.BuildServerTLSConfig(mtls.Config{
		CertFile: certPath, KeyFile: keyPath, CAFile: caPath,
	})
	require.NoError(t, err)
	require.Equal(t, mtls.ModeMTLS, mode)
	require.NotNil(t, cfg.GetCertificate)
	require.Empty(t, cfg.Certificates,
		"hot-reload config must use GetCertificate, not the static Certificates slice")

	cert1, err := cfg.GetCertificate(&tls.ClientHelloInfo{})
	require.NoError(t, err)

	// Same mtime → cache hit → same pointer.
	cert1Again, err := cfg.GetCertificate(&tls.ClientHelloInfo{})
	require.NoError(t, err)
	require.Same(t, cert1, cert1Again,
		"GetCertificate must return cached cert when file unchanged")

	// Rewrite the cert files, then bump mtime explicitly so coarse
	// filesystem timestamps don't fool the staleness check.
	writeLeafCert(t, certPath, keyPath, caPath)
	touchAhead(t, certPath)

	cert2, err := cfg.GetCertificate(&tls.ClientHelloInfo{})
	require.NoError(t, err)
	require.NotSame(t, cert1, cert2,
		"GetCertificate must reload after cert file mtime changed")
	require.NotEqual(t, cert1.Certificate[0], cert2.Certificate[0],
		"reloaded cert DER bytes must differ from the cached one")
}

// TestBuildClientTLSConfig_HotReloadsRotatedCert mirrors the server-side
// rotation test: the client GetClientCertificate callback must also
// pick up rotated cert files.
func TestBuildClientTLSConfig_HotReloadsRotatedCert(t *testing.T) {
	dir := t.TempDir()
	certPath := filepath.Join(dir, "cert.pem")
	keyPath := filepath.Join(dir, "key.pem")
	caPath := filepath.Join(dir, "ca.crt")

	writeLeafCert(t, certPath, keyPath, caPath)

	cfg, mode, err := mtls.BuildClientTLSConfig(mtls.Config{
		CertFile: certPath, KeyFile: keyPath, CAFile: caPath,
	})
	require.NoError(t, err)
	require.Equal(t, mtls.ModeMTLS, mode)
	require.NotNil(t, cfg.GetClientCertificate)
	require.Empty(t, cfg.Certificates)

	cert1, err := cfg.GetClientCertificate(&tls.CertificateRequestInfo{})
	require.NoError(t, err)

	writeLeafCert(t, certPath, keyPath, caPath)
	touchAhead(t, certPath)

	cert2, err := cfg.GetClientCertificate(&tls.CertificateRequestInfo{})
	require.NoError(t, err)
	require.NotSame(t, cert1, cert2)
	require.NotEqual(t, cert1.Certificate[0], cert2.Certificate[0])
}

